<?php
namespace Xdecaro\Component\Decarocourses\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\Database\DatabaseInterface; use RuntimeException;
final class AnalyticsSourceService { private DatabaseInterface $db; public function __construct(DatabaseInterface $db){$this->db=$db;} public function getMetrics():array{$this->auth();return [['key'=>'courses.total','label'=>'Courses'],['key'=>'courses.editions.total','label'=>'Editions'],['key'=>'courses.editions.published','label'=>'Published editions'],['key'=>'courses.capacity.total','label'=>'Total capacity'],['key'=>'courses.registration.open','label'=>'Open registrations']];} public function getDatasets():array{$this->auth();return [['key'=>'courses.editions.by_status','label'=>'Editions by status'],['key'=>'courses.editions.by_year','label'=>'Editions by academic year'],['key'=>'courses.editions.upcoming','label'=>'Upcoming editions']];} public function getMetric(string $key,array $context=[]):array{$this->auth();if($key==='courses.total')return ['value'=>$this->count('#__decarocourses_courses','state'),'label'=>'Courses'];if($key==='courses.editions.total')return ['value'=>$this->count('#__decarocourses_editions','state'),'label'=>'Editions'];if($key==='courses.editions.published')return ['value'=>$this->count('#__decarocourses_editions','state'),'label'=>'Published editions'];if($key==='courses.capacity.total'){$q=$this->db->getQuery(true)->select('COALESCE(SUM('.$this->db->quoteName('capacity').'),0)')->from($this->db->quoteName('#__decarocourses_editions'))->where($this->db->quoteName('state').' = 1');return ['value'=>(int)$this->db->setQuery($q)->loadResult(),'label'=>'Total capacity'];}if($key==='courses.registration.open'){$today=Factory::getDate('now','UTC')->format('Y-m-d');$q=$this->db->getQuery(true)->select('COUNT(*)')->from($this->db->quoteName('#__decarocourses_editions'))->where($this->db->quoteName('state').' = 1')->where('('.$this->db->quoteName('registration_start').' IS NULL OR '.$this->db->quoteName('registration_start').' <= :today)')->where('('.$this->db->quoteName('registration_end').' IS NULL OR '.$this->db->quoteName('registration_end').' >= :today)')->bind(':today',$today);return ['value'=>(int)$this->db->setQuery($q)->loadResult(),'label'=>'Open registrations'];}throw new \InvalidArgumentException('Unknown Courses metric: '.$key);} public function getDataset(string $key,array $context=[]):array{$this->auth();$limit=max(1,min(500,(int)($context['limit']??100)));if($key==='courses.editions.by_status')return $this->group('status',$limit);if($key==='courses.editions.by_year')return $this->group('academic_year',$limit);if($key==='courses.editions.upcoming'){$today=Factory::getDate('now','UTC')->format('Y-m-d');$q=$this->db->getQuery(true)->select(['id','course_id','title','academic_year','start_date','end_date','registration_end','capacity','status'])->from($this->db->quoteName('#__decarocourses_editions'))->where($this->db->quoteName('state').' = 1')->where($this->db->quoteName('start_date').' >= :today')->order($this->db->quoteName('start_date').' ASC')->bind(':today',$today);return array_values((array)$this->db->setQuery($q,0,$limit)->loadAssocList());}throw new \InvalidArgumentException('Unknown Courses dataset: '.$key);} private function count(string $table,string $state):int{$q=$this->db->getQuery(true)->select('COUNT(*)')->from($this->db->quoteName($table))->where($this->db->quoteName($state).' = 1');return (int)$this->db->setQuery($q)->loadResult();} private function group(string $field,int $limit):array{$q=$this->db->getQuery(true)->select([$this->db->quoteName($field),'COUNT(*) AS total'])->from($this->db->quoteName('#__decarocourses_editions'))->where($this->db->quoteName('state').' = 1')->group($this->db->quoteName($field))->order('total DESC');return array_values((array)$this->db->setQuery($q,0,$limit)->loadAssocList());} private function auth():void{$u=Factory::getApplication()->getIdentity();if(!$u->authorise('core.manage','com_decarocourses')&&!$u->authorise('core.admin','com_decarocourses'))throw new RuntimeException('Not authorised to read Courses analytics.',403);} }
